input.command:
cd ~/leveraged-etf-risk-analytics/.claude/worktrees/recovery-harness; H=data/outputs-recovery/preflight/preflight-4/harness.jsonl; C=data/outputs-recovery/preflight/preflight-4.console.log; until [ -f "$H" ] || grep -q "harness exit=" "$C" 2>/dev/null; do sleep 1; done; [ -f "$H" ] || { tail -5 "$C"; exit 0; }; tail -n +1 -f "$H" | .venv/bin/python -u -c '
import json, sys
keep = {"setup_error", "reference_step", "armed", "injection", "job_done", "job_error", "not_run", "quiescent", "final_snapshot", "final_error", "batch_ended", "host_state"}
for line in sys.stdin:
    try:
        e = json.loads(line)
    except ValueError:
        continue
    ev = e.get("event")
    if ev not in keep:
        continue
    if ev == "host_state":
        f = {"stage": e.get("stage"), "position": e.get("position"), "power": e.get("power_source"), "lid_closed": e.get("lid_closed"), "pressure": e.get("memory_pressure"), "available_GiB": round(e["available_bytes"] / 2**30, 2), "swap_GiB": round(e["swap_used_bytes"] / 2**30, 2)}
    elif ev == "final_snapshot":
        f = {k: e.get(k) for k in ("status_check_exit", "cleanup_exit", "fingerprints_agree")}
    elif ev == "quiescent":
        f = {"processes_left": e.get("processes_left"), "other_connections": e.get("other_connections"), "scratch_new": len(e.get("spark_scratch_new") or [])}
    else:
        f = {k: e.get(k) for k in ("step", "exit", "position", "case", "kind", "worker", "missed", "final", "stop_reason", "error") if e.get(k) is not None}
    print(ev, json.dumps(f, default=str)[:240], flush=True)
    if ev == "batch_ended":
        break
' & P=$!; while kill -0 $P 2>/dev/null && pgrep -f "etf_risk.jobs.harness batch" >/dev/null; do sleep 2; done; sleep 2; kill $P 2>/dev/null; grep "harness exit=" "$C" || echo "harness exit not yet recorded"

